<style>
.msl-loader {
  position: fixed;
  inset: 0;
  z-index: 9999;
  overflow: hidden;
}

.msl-center {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 28px;
}

/* 霧面紋理：極淡的雜訊，避免大面積色塊看起來死板 */
.msl-grain {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  opacity: 0.025;
  pointer-events: none;
  mix-blend-mode: multiply;
}

.msl-logo-stack {
  position: relative;
}
.msl-logo {
  display: block;
}
.msl-logo-wipe {
  position: absolute;
  inset: 0;
}

.msl-bar-track {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  width: 100%;
  height: 4px;
  background: rgba(255, 255, 255, 0.25);
  overflow: hidden;
  border-radius: 0;
}
.msl-bar-fill {
  width: 100%;
  height: 100%;
  background: #ffffff;
  transform-origin: left center;
}
</style>